import logging
from moler.device import DeviceFactory
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.utilities.cpu_count import CpuCount
from taf.rfrl.bts.connections import device_aliases as connection_names


@load_moler_configuration_from_tl()
def start_gnb_cpu_monitoring(bts_id=0, du_id=0, interval=10):
    """
    Start monitoring of CPU on gnb and local unix.

    :param interval: time in seconds between measurements.
    :param bts_id:      enb_id or gnb_id, related to test line configuration, default set to 0
    :param du_id:       DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
    :return: None.
    """
    interval = int(interval)
    cpu_count = CpuCount.get_instance()
    gnb_device_name = connection_names.ssh_bts_du.format('GNB', bts_id, du_id)
    gnb = DeviceFactory.get_device(name=gnb_device_name)
    cpu_count.add_device(name=gnb.name, state='FCT', clone=True)
    cpu_count.set_interval(interval=interval)
    cpu_count.start_observer()


@load_moler_configuration_from_tl()
def stop_gnb_cpu_monitoring():
    """
    Stop monitoring of CPU.

    :return: None.
    """
    cpu_count = CpuCount.get_instance()
    cpu_count.stop_observer()


def calculate_average_cpu(bts_id=0, du_id=0, prefix='cpu'):
    gnb_device_name = connection_names.ssh_bts_du.format('GNB', bts_id, du_id)
    gnb_device_name = '{}_{}'.format(prefix, gnb_device_name)
    cpu_count = CpuCount.get_instance()
    logging.debug("Stared CPU stats {}".format(cpu_count._stored))

    cpu_samples = []
    start_time = cpu_count._stored[gnb_device_name][0]['time']
    end_time = cpu_count._stored[gnb_device_name][-1]['time']
    duration = end_time - start_time
    for sample_record in cpu_count._stored[gnb_device_name]:
        cpu_samples.append(100 - sample_record['not used'])

    avg_cpu = round(sum(cpu_samples) / len(cpu_samples), 2)
    logging.info("Calculated CPU AVG: {}".format(avg_cpu))
    logging.info("Data collected from {} to {}. Duration {}".format(start_time, end_time, duration))
    return avg_cpu


def clear_stored_cpu_stats():
    cpu_count = CpuCount.get_instance()
    cpu_count._stored = dict()
